function ExecImage(props) {
	const nameTxt = '${props.name}'.replace('_',' ')
	return(
	<div className="flex flex-col mb-50 align-bottom">
		<img
            className="w-4/5 h-4/5"
			src={props.name}
			alt={nameTxt}

		/>
		<p className="mt-20px text-lg">{nameTxt}</p>
    <p>{props.year}</p>
	</div>
	);
}
export default ExecImage;
